import Image from "next/image";

/* Brand lockups (Hairline ring) are generated by design/build-hairline.mjs into public/brand/.
   The site is light only; `reversed` is for dark surfaces such as the footer. */
export function Logo({ height = 40, reversed = false }: { height?: number; reversed?: boolean }) {
  const width = Math.round(height * 2.472);
  if (reversed) {
    return <Image src="/brand/lockup-solid-reversed.svg" alt="Aston Business Intelligence" width={width} height={height} style={{ height, width: "auto" }} />;
  }
  return (
    <Image src="/brand/lockup-solid.svg" alt="Aston Business Intelligence" width={width} height={height} priority style={{ height, width: "auto" }} />
  );
}

export function Mark({ size = 32, variant = "solid" }: { size?: number; variant?: "solid" | "metallic" | "badge" }) {
  return <Image src={variant === "badge" ? "/brand/badge.svg" : `/brand/mark-${variant}.svg`} alt="" width={size} height={size} />;
}
